-- Forms & words keeps the asks that hold for every word: an expression's particle and verb asks are for verbal idioms
-- (a noun phrase answered with a raw id), its range repeated its meaning; a word's "meaning here" drew senses that do
-- not fit (قَابِل → the one who takes the bucket from the well)
UPDATE qr_study_label
   SET extra_json = json_set(extra_json,
         '$.only.vocab', json('["vocab_root","vocab_lemma","vocab_family","vocab_form","vocab_kin","vocab_range","vocab_same"]'),
         '$.only.expression', json('["ex_meaning","ex_note","ex_where"]'))
 WHERE scope = 'class_node' AND key = 'words';
